import { MODELS } from './modelConfig';
import { createPanelCard, createPanelGroup, type PanelCard } from './ModelPanel.ts';
import type { ModelConfig } from './modelConfig';

// ------------------------------------------------------------
// Model embeds for description pages
//
// Put an empty element on the page:
//
//     <div class="model-embed" data-model="ERAM"></div>
//
// data-model must match a model's `name` in modelConfig.ts. The panel
// (viewport, Pause / Resume, Fullscreen, Download) is built from the
// same code as the models page. Each viewer is only created when its
// embed first becomes visible, so collapsed dropdowns cost nothing.
//
// The page also needs the fullscreen layer from models.html
// (#fullscreen-backdrop, #fullscreen-controls, #fs-toggle, #fs-minimize).
// ------------------------------------------------------------

interface PendingEmbed {
    model: ModelConfig;
    card: PanelCard;
}

document.addEventListener('DOMContentLoaded', () => {

    const embeds = document.querySelectorAll<HTMLElement>('.model-embed[data-model]');

    if (embeds.length === 0) {
        return;
    }

    const backdrop = document.getElementById('fullscreen-backdrop');
    const controls = document.getElementById('fullscreen-controls');
    const toggleBtn = document.getElementById('fs-toggle') as HTMLButtonElement | null;
    const minimizeBtn = document.getElementById('fs-minimize') as HTMLButtonElement | null;

    if (!backdrop || !controls || !toggleBtn || !minimizeBtn) {
        console.error('[model embeds] the fullscreen layer is missing from this page.');
        return;
    }

    const group = createPanelGroup({ backdrop, controls, toggleBtn, minimizeBtn });

    // Embeds waiting to become visible
    const pending = new Map<Element, PendingEmbed>();

    const observer = new IntersectionObserver((entries) => {

        for (const entry of entries) {

            if (!entry.isIntersecting) {
                continue;
            }

            const item = pending.get(entry.target);

            if (!item) {
                continue;
            }

            pending.delete(entry.target);
            observer.unobserve(entry.target);

            group.mount(item.model, item.card);
        }

    }, { rootMargin: '200px' });

    embeds.forEach((embed) => {

        const name = embed.dataset.model;
        const model = MODELS.find((candidate) => candidate.name === name);

        if (!model) {
            embed.textContent = `Unknown model "${name}".`;
            console.error(`[model embeds] no model named "${name}" in modelConfig.ts`);
            return;
        }

        // The description page is the model's own page, so no Description link.
        const card = createPanelCard(model, { showDescription: false });

        embed.append(card.section);

        pending.set(embed, { model, card });
        observer.observe(embed);
    });
});